# How many new 3s are at distance 1-2 from orig_3s (via any path of 0s)?
def bfs_distance(grid, start, target):
    """BFS on 0-cells only"""
    from collections import deque
    if grid[start[0]][start[1]] != 0:
        return float('inf')

    visited = [[False]*13 for _ in range(21)]
    queue = deque([(start, 0)])
    visited[start] = True

    while queue:
        curr, dist = queue.popleft()
        if curr == target:
            return dist

        r,c = curr
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < 21 and 0 <= nc < 13 and grid[nr][nc] == 0 and not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append(((nr,nc), dist+1))
    return float('inf')

