# Find all maximal rectangular regions of 3s in output
def find_rectangles(grid, value):
    """Find all maximal axis-aligned rectangles of given value"""
    rectangles = []

    # Scan for top-left corners
    visited_cells = set()

    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r,c] == value and (r,c) not in visited_cells:
                # Grow rectangle in both directions
                max_h = 1
                max_w = 1

                # Check vertical growth
                while r + max_h < grid.shape[0]:
                    can_extend = True
                    for cc in range(c, c + max_w):
                        if grid[r + max_h, cc] != value:
                            can_extend = False
                            break
                    if can_extend:
                        max_h += 1
                    else:
                        break

                # Check horizontal extension from top-left
                max_w_temp = 1
                while c + max_w_temp < grid.shape[1]:
                    can_extend = True
                    for rr in range(r, r + max_h):
                        if grid[rr, c + max_w_temp] != value:
                            can_extend = False
                            break
                    if can_extend:
                        max_w_temp += 1
                    else:
                        break
                max_w = max(max_w, max_w_temp)

                rect = (r, c, max_h, max_w)
                visited_cells.add((r,c))
                rectangles.append(rect)

                # Mark all cells in this rectangle as visited
                for rr in range(r, r + max_h):
                    for cc in range(c, c + max_w):
                        visited_cells.add((rr,cc))

    return rectangles

